INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1115809-mgt210', 'stk-fin_analyst', 'MGT 210', 'info', '{"desc": "^^\n\nالكورس معايا الآن … يتحدث عن مهارات الاتصال في البزس ,وكيف الواحد لازم يوصل معلوماته بوضوح وياخذ باعتبار عوامل مختلفة اقتصادية وثقافية وغيرها… الكورس بسيط وفيه معلومات حلوة…\n\nفيه case study كانت عن كيفية ايصال الاخبار السيئة للموظفين مثل تقليل الرواتب , او الغاء البدلات وكذا … مرة سهلة لاتشيل همها … بتكون في قروب مكون من 6-8 اشخاص\n\nوفيه ايضاً البرزنتيشن سكليز مهمة جدا … في الكورس راح تسوي برزنتيشن فردي, وحتكون مقسمة على 3 مرات يعني كل اسبوع جزء يمكن … الموضوع انت تختاره…واللي يهم في البرزنتيشن مهارتك على الاقناع, لغة جسدك., وثقتك بنفسك وكذا\n\nوفيه ريبورت قصير في نهاية السميستر ماعندي اي معلومات عنه للان…\n\n^^\nطبعا الكورس انا منزل مع Edward Joyner فيمكن الكلام يختلف مع دكتور ثاني\n\nاي اسئلة اخرى انا حاضر", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-210-business-communication/120987/3", "user": "FIN_Analyst", "ts": 1352663975000, "tid": 120987, "pn": 3}}', 1352663975000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1391772-mgt210', 'stk-a_o_s_ll', 'MGT 210', 'info', '{"desc": "كورس مفيد جدا جدا في تطوير مهارات التواصل\nفيه تطوير لمهارات البريزنتيشن وكتابة السيرة الذاتية\nوكيفية ادارة الاجتماعات وايصال الاخبار السيئة وكيف\nالتعامل مع المقابلات بشكل عام …\n\nوالكورس سهل وتقدر تطلع منه بقريد عالي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-210-business-communication/120987/7", "user": "A_O_S_ll", "ts": 1408630964000, "tid": 120987, "pn": 7}}', 1408630964000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1440424-mgt210', 'stk-azooz_jk', 'MGT 210', 'info', '{"desc": "جودة المقرر بشكل عام\nجدا مفيييد ممتع و(طويـــل)\n\nالمواضيع التي يغطيها المقرر\n\nالكتاب المستخدم للمقرر\nكويس اشووفو صح انو طوييل\n\nالأسئلة والأمثلة المستخدمة في المقرر\nيعتمد على دكتورك اذا تي بي او لا على العموم قرا من بدري ولا حتخبص\nا\nمدى فائدته في الناحية التطبيقية\nجدا جدا مفييد\n\nمادة ستاندر وقريد اغلب الشعب يقول اشياء بديهية ويخبص عشان كدا اقرا الكتاب وركز وكمان عشان تقدر تحل الاسئلة المقالية", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-210-business-communication/120987/9", "user": "Azooz_Jk", "ts": 1453652345000, "tid": 120987, "pn": 9}}', 1453652345000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1453423-mgt210', 'stk-user10207', 'MGT 210', 'info', '{"desc": "المادة تتكلم عن التواصل في مجال البزنس.\nافادتني اكثر من انجلش ٢١٤\nلان فيها اشياء تطبيقية اكثر مثل\nالبرزنتيشن: فيه 3 برزنتيشن تسويها طول السمستر.\nفي خطوات لازم تسويها عشان البرزنتيشن\nيكون ناجح موبس وداخله بالدرجات… مثل لغة الجسد والصوت والكلام والنظر والخ…\nفيه هوموركات مناقشة على البلاكبورد.\nفيه بعد مقابلة شخصية مع المدرس وانت الي تكتب الاسئلة وتجاوب عليها.\nفيه بعد تكتب ايميل وتعدل عليه. وايضا السيرة الذاتية.\nالسيرة الذاتية راح يدقق عليها المدرس مش زي الانجلش ٢١٤\nوايضا مناقشة شفوية داخل الكلاس مع القروب تبعك مع ناس ثانين (اجتماع)\nوشورت ريبورت… واشياء ثانية.\n\nاسم الكتاب Communicating in Business\nالـ A+ من 95. الكورس جدا سهل لاتطير عليك الدرجات خصوصا بالمدترم شوي صعب.\nالاختبارات مدترم وفاينل صح وخطا واختيارات ورتن كتابة اغلبها من الكتاب وفيه من الملفات الي\nيرفعها المدرس في البلاكبورد. الاسئلة مو كلها مباشرة. فيه اسئلة يبيلك تقرأ من الكتاب وتركز.\nالي يدرسها اثنين ماكسويل وادوارد… كلهم كويسين بس يمدحون ماكسويل. بالتوفيق.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-210-business-communication/120987/10", "user": "user10207", "ts": 1468138505000, "tid": 120987, "pn": 10}}', 1468138505000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1518526-mgt210', 'stk-user11151', 'MGT 210', 'info', '{"desc": "نزلت المادة كمقرر اختياري وندمت أشد الندم.\nمادة مملة جدًّا جدًّا جدًّا لدرجة تخليك تسحب على كل شي.\n\nالمادة سهل تجيب فيها قريد وسهل بعد تخسر قريد لذلك كن حذر.\nالمادة تختبر صبرك في تسليم المتطلبات المملة، وأيضًا اللي لغتهم ضعيفة بيعانون لأن المد والاختبار النهائي كلها قراءة من الكتاب بالتفصيل وفيه منها عدد.\n\nأخيرًا إذا بتصبر على الغثا نزلها وانتبه تتأخر في تسليم شي لأن زي ما ذكرت راح تطير عليك قريدات من واجب واحد فقط!", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-210-business-communication/120987/11", "user": "user11151", "ts": 1577812109000, "tid": 120987, "pn": 11}}', 1577812109000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1519211-mgt210', 'stk-feras-mtn', 'MGT 210', 'info', '{"desc": "Term 191\n\nخذيتها مع ماكسويل\n\nجودة المقرر بشكل عام:\nمفيييد جدا\nالمواضيع التي يغطيها المقرر\nمثل ماقالو الشباب التواصل في مجال العمل\nالكتاب المستخدم للمقرر\nحشو كلام …\nالأسئلة والأمثلة المستخدمة في المقرر\nالميد والفاينل كان نسخ لصق من Test Bank وبتلقونه في KFUPM Resource لكن الدكتور كان يشدد انه نذاكر من الكتاب وفعلا جاء سؤال\nسؤالين مو من التيست بانك\nالميد والفاينل عند ماكسويل كان عبارة عن جزئين …\nالجزء الاول اختيارات (نسخ لصق من الTB)\nالجزء الثاني (عرف، عدد، اعطيني رايك) مثل اللي في التيست بانك لكن جاء سؤال سؤالين تقريبا ماكانت من التيست بانك و يعطيك 7 أسئلة يقلك اذا حليت 5 منهم تاخذ كامل في جزئية المقالي\n\n+ اسحب عالصح والخطأ بالTB لانه ضياع وقت في المذاكرة الا اذا قالولكم الاختبار بيكون فيه صح وخطأ بس هوا نبهنا قبلها وقال مافي\n\nطلعت بالكورس بA … مجموعي كان 94.20 ومازادني 😦\n\nوطريقة مذاكرتي كان يرسلنا study guide اسئلة وتدور على اجوبتها من الكتاب كانت طويلة للامانه … وكانت تاخذ مني يوم ونص الى يومين وبعدين اجلس يوم كامل عالتيست بانك اغطي الاجابة واحاول احله والسؤال اللي اغلط فيه احدد عليه عشان ارجع احاول فيه بعدين واخلص التسيت بانك وارجع احله ثاني مرة كامل وثالث مرة قبل الاختبار والتيست بانك طويل برضو فلا تستسهله ساعتين-ثلاثة تقريبا لكل شابتر … لكن الطريقة هذي خلتني اجيب فل في الاختيارات بالميد والفاينل ولا خلتني اكمل اقرا السؤال كامل الا وحطيت الاجابة وعاد الجزء الثاني حق عدد وعرف تعتمد على قوة حفظك\n\nوالمتطلبات مو كرف ولا شي وبالعكس خفيفة كلها تعمل برزنتشين عن شي تبغا تقنع الناس تشتريه و وريبورت صفحة وحدة تعمله لمشكلة صارت في شركتك وبترفع عليه ريبورت (ابدا مو مثل ريبورتات الانقلش 214 وبالعكس تفيدك تعلمك كيف تكتب الريبورتات القصيرة هذي مستقبلا اذا توظفت) والحاجتين موضوعها من اختيارك\n\nمدى فائدته في الناحية التطبيقية\n\nللامانه تستفيد لكن صعب تتذكرها وتطبقها في الواقع … والملفات والسلايدات اشوفها مراجع جدا قيمة تفيدك لبعدين اذا احتجت تعمل سي في ولا بريزنتيشن وتحتاج تعمله فاحسن صوره ولا اضطريت تنقل اخبار سيئة\n\nانا طالب هندسة وللامانه استمتعت في الكورس وابدا ماكان ممل مع الدكتور ماكسويل وبالعكس ماتحس بالوقت معاه (قد تختلف الاراء) … لكن في النهاية ابدا ماندمت وبالعكس الكورس خلاني اشوف فرق السهولة بين مواد الادارة والهندسة وخلاني افكر اهرب للادارة لكن للاسف فات القطار 👋", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-210-business-communication/120987/12", "user": "Feras-MTN", "ts": 1579485928000, "tid": 120987, "pn": 12}}', 1579485928000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p643954-mgt210', 'stk-g_u_c_c_i', 'MGT 210', 'info', '{"desc": "أمتع كورس أخذته في kfupm مع هالدكتور … من ناحية التحضير ما درى عنك\nودك تحضر إحضر ما ودك أنت الخسران - هذا نظامه - وفي النهاية ما يناظر في الكلاس\nوورك بشكل أساسي , القريد إن كنت مهتم بالمادة تاخذ الـ a+ بالراحة …\n\nأما إن كنت مش حالك , تطلع بـ c إلى b … مافي أي كرف , البرزنتيشنز شربة موية ,\nوفي زي ما تقول بروجكت يُسمى CASE STUDY على ما أذكر بسيط ممتع جداً جداً ولا\nفيه شغل كثير … الكورس بتستفيد منه كثير …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt210/90840/3", "user": "G_U_C_C_I", "ts": 1277473860000, "tid": 90840, "pn": 3}}', 1277473860000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p174504-mgt210', 'stk-gmc', 'MGT 210', 'srcU', '{"html": "ادري<br>بعد شوي الفاينل<br>بس يمكن يفيد أجيال المستقبل@4@<br><br>هذا ملف ملخص (ناقص بعض الأشياء) للكونتنس اللي في السايت حق الدكتور دانيال<br><br>دعواتكم بس@46@<br><br>​<span data-fid=\"stk-f174504-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f174504-0": {"name": "OutLine 4 MGT210.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt210/56768/1", "user": "GMC", "ts": 1181443934000, "tid": 56768, "pn": 1}}', 1181443934000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ksa-wolf-mgt210', 'stk-ksa-wolf', 'MGT 210', 'doc', '{"docs": [{"id": "stk-dr-f99897", "n": "Dr. Edward M. Joyner", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MGT 210 --- Term 152\n\nالتحضير:\nيحضر كل كلاس في وسطه أو نهايته…\nطريقة الشرح:\nيشرح أحيانا من السلايدات و أحيانا من الكتاب… و قد يستخدم الكتاب لحل تمارين…\nطريقة المذاكرة:\nذاكر السلايدات و المقالات اللي يحطها لك في البلاكبورد و لا تعتمد على التي بي لأن الإدارة مشددة على أغلب المدرسين أنهم لا يحطون الأسئلة منه.\nالكويزات:\nما فيه … فيه assignments و نقاشات على البلاك بورد و عليها درجات…\nالأسايمنتز مهمه و عليها نسبة كبيرة…\nالمياجر: >> ميد تيرم في الحقيقة\nأغلبها برا التي بي و من الكتاب و المقالات على البلاك بورد و تكون سهلة.\nخيارات و أسئلة مقالية و صح و خطأ…\nالفاينلات:\nمثل المياجر\nالقريد النهائي:\nأعطيه A… بس الدكتور ما يمشي ، يعني تأخذ حقك.\nالصوت:\nواضح\nإضافات\nالميد ترم مهم جدا لا تضيعه أو تستهين فيه…\nما شديت ذيك الشدة و طلعت ب B >> الميدتيرم هو اللي طير قريدين علي.\n\nالسيلابس على الرابط تحت في القوقل درايف يا أنا… 😆\nhttps://drive.google.com/file/d/0Bybkny3pDzc-OUJjR0swc3lNSzA/view?usp=sharing\n\nبالتوفيق,", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1452924-mgt210", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-edward-m-joyner/99897/19", "user": "KSA-WOLF", "ts": 1467259669000, "tid": 99897, "pn": 19}}]}', 1467259669000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-maxmx05-mgt210', 'stk-maxmx05', 'MGT 210', 'doc', '{"docs": [{"id": "stk-dr-f99897", "n": "Dr. Edward M. Joyner", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "TERM 171\n\nMGT 210\n\nالاسبوع 9\n\nالتحضير : التحضير عليه 5%. فانتبه لهذي النقطة. عادي تجي متاخر الى 20 دقيقة وراح يحضرك.\nطريقة الشرح : سلايدات ويتكلم عليها و يعطيك من خبرته العريقة في الادارة في شركات كثيرة. يتكلم عن نقطة ويسولف عليها\nالكويزات : كويزين كل واحد عليع 2.5 % من درجة الكورس من السلايدات وملفات ال PDF اللي يعطيكم ايهاها في البلاك بورد. يعني تذاكر تجيب ما تذاكر ما تجيب لانها حفظ.\nالمياجر: ميدترم تذاكرة من ( الكتاب ) متوسط الصعوبة\nالفاينلات : ما بعد\nالقريد النهائي: A\nالصوت: واضح\nإضافات :\nالدكتور حبيب\nاشوف الطلاب يقعدون على الجوال ما يقول لهم شيء\nالدكتور متمكن في المادة بشكل كبير جدا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1483293-mgt210", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-edward-m-joyner/99897/20", "user": "Maxmx05", "ts": 1510506200000, "tid": 99897, "pn": 20}}]}', 1510506200000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-jafar_15-mgt210', 'stk-jafar_15', 'MGT 210', 'doc', '{"docs": [{"id": "stk-dr-f99897", "n": "Dr. Edward M. Joyner", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MGT210 - 172\n\nالتحضير :\nبشكل شبه يومي، مايشدد كثير على التاخير. يقبل الميكب اذا رسلت له على الايميل قبل الكلاس. عليه خمس درجات.\n\nطريقة الشرح :\nيفتح السلايدات ويبدا يشرح ويعلق، بالنسبة لي كان شرحه جدًا ممل، لكن المادة بشكل عام ماتحتاج شرح المادة بسيطة وسهلة جدًا. يعني تقرا الكتاب شي كافي ووافي\n\nالكويزات :\nعطانا كويزين رتن، سهلة الى متوسطة. غالبا تكون عدد. مذاكرة الكويزات بتكون من Articles يحطها لكم في البلاكبورد.\n\nالمياجر :\nالمادة فيها مد ترم، بيحدد لكم قبله من الكتاب الاشياء المهمة هذي ركز عليها بتجيك بنسبة كبيرة. المد فيه خيارات ورتن، جزء الخيارات يُقال انه TB لكن انا مافتحته فماني متاكد من هالنقطة. جزء الرتن يشبه الكويزات. باختصار سهل الى متوسط. المذاكرة تكون من الكتاب. المد فيه 5 شابترات\n\nالفاينلات :\nالفاينل نفس نظام المد، رتن وخيارات. جزء الرتن بيركز غالبًا على تصحيح كتابة جملة ، بيجيكم شابتر وبيقول لكم عليه وهو يشرح. بيكون شابترات جديدة غير اللي اختبرتوا فيها في المد. سهل الى متوسط.\n\nالصوت :\nتقدر تقول ضعيف الى متوسط.\n\nإضافات :\nمايعطي بونص، لكن المادة سهلة وتجميع الدرجات فيها بسيط. ركز معاه في الكلاس واعرف المطلوب منه تمام ويمشيك خصوصا في البرزنتيشن الاخير. تصحيحه اشوفه جدا متساهل، يعني حاول ماتترك اي فراغ سواء كويز، مد او فاينل واكتب شي قريب او له علاقة بالسؤال و يعطيك عليها درجات من واقع تجربة.\nبيقسمكم قروبات عشان Case study. كل ماتبدعون كل مايجيكم درجات اكثر. وفي ريبورت قصير حوالي صفحتين ثلاث عليه 5 درجات.\n\nمجملا الدكتور جدا ممتاز، ممكن اللي بيفرق عنه هو وماكسويل ممكن نقطة البونص. لكن المادة سهلة وبسيطة ومايحتاج تفكر في البونص.\n\nفي المرفقات درجات الطلاب لترم 172", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1498420-mgt210", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-edward-m-joyner/99897/22", "user": "Jafar_15", "ts": 1535628072000, "tid": 99897, "pn": 22}}]}', 1535628072000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10407-mgt210', 'stk-user10407', 'MGT 210', 'doc', '{"docs": [{"id": "stk-dr-f99897", "n": "Dr. Edward M. Joyner", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MGT 210 - 172\nالتحضير : كل كلاس\nطريقة الشرح : من سلايدات و يتكلم كثير غير ممل و يحب يشطح و يتكلم عن نفسه\nالكويزات : من مقالات ينزلها على البلاكبورد ( مقاربة للمنهج )\nالمياجر: ميدتيرم عليه 20% من الكتاب - متوسط\nالفاينلات : نفس الميدتيرم بس عليه 25%\nالقريد النهائي: A\nالصوت: واضح\nإضافات : المادة لازم تلتزم بالحضور لان بالعادة كل كلاس يكون فيه شيء ( كويز هوم وورك ستدي كيس او ايميل )\nالبرزنتيشن عليه 15% اتبع تعليمات الدكتور و تاخذها ( يدقق كثير في البرزنتيشن )", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1501564-mgt210", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-edward-m-joyner/99897/23", "user": "user10407", "ts": 1540823606000, "tid": 99897, "pn": 23}}]}', 1540823606000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kbsc-mgt210', 'stk-kbsc', 'MGT 210', 'doc', '{"docs": [{"id": "stk-dr-f99897", "n": "Dr. Edward M. Joyner", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Edward Joyner\n\nالمادة: *\n\nMGT 210\n\nطريقة الشرح : *\n\nيركز ع المهم والمفيد ، ينقل بعض القصص من خبراته\n\nالكويزات :\n\nسهلة\nالمياجر/ميد:\n\nمن شرحه ، سهل\n\nالفاينل :\n\nمن شرحه ، لكن منهج الفاينل أصعب شوي\n\nطريقة التحضير :\n\nنهاية الكلاس\n\nالقريد النهائي الخاص بك :\n\nA\n\nاضافات:\n\nالكورس معه مفيييد جدا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1507362-mgt210", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-edward-m-joyner/99897/24", "user": "KBSC", "ts": 1552816977000, "tid": 99897, "pn": 24}}]}', 1552816977000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2352-mgt210', 'stk-user2352', 'MGT 210', 'doc', '{"docs": [{"id": "stk-dr-f118970", "n": "Dr. Maxwell Heineck", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "mgt210-\nالمدرس كان يدرس في الأوريا وصار الحين في قسم الادارة\nالتحضير :دقيق جدا لدرجة إنه يحاسب على التأخير والغياب 5%\nطريقة الشرح : سلايدات من موقع خاص فيه يضعه لنا في الوب سيتي ويطلب تحضير الدرس ويناقش ويسأل ويعطينا نبذه عن المهم ،،\nالكويزات : سهلة من السلايات ،،،\nالمياجر: يحدد لنا المطلوب من الكتاب وطريقة الاسئلة بلإضافة للسلايدات والمقالات\nالفاينلات : نفس المياجر ويعطيك الزبدة والخلاصة مسائل مراجعة تحلها وتقرأها من الكتاب\nالقريد النهائي: B ونظامه ستاندارد\nالصوت: واضح ومسموع ولغته ممتازة أمريكي من نيويورك\nإضافات : فيه CASE STUDY تسويها مع قروب عليها 5% , وفيه برزنتيشن تسويها على 3 مراحل 20% ،، وفيه SHORT REPORT عن اي موضوع تختاره 5% والكورس صراحه مفيد لتطوير مهارات اللغة والاتصال ،،", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1215514-mgt210", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/maxwell-heineck/118970/8", "user": "user2352", "ts": 1366790433000, "tid": 118970, "pn": 8}}]}', 1366790433000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2838-mgt210', 'stk-user2838', 'MGT 210', 'doc', '{"docs": [{"id": "stk-dr-f118970", "n": "Dr. Maxwell Heineck", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الكورس Mgt 210 الترم 131\n\nالتحضير : يحضر يوميا نهاية كل محاضرة و ما يهتم بالتأخير أبد… أنا غبت عنده 6 غيابات و خصم علي درجتين فقط !!\n\nطريقة الشرح: شرحه ممتاااااز جدا … يعطيك اللي راح يصير في المحاضرة في الويب ستي و الوضع سهالااااات\n\nالكويزات : ما في كويزات ولا واجبات،مرتين بس طلب منا قروب ديسكشن و اخذ اوراق كل قروب و عطانا فل مارك\n\nالمياجر: نصها مولتبل تشويز من التي بي و نصها أسئلة ريتين … أسئلة الريتين من المادة اللي في الويب سيتي و سهلة …\n\nالفاينل: مولتبل تشويز و تي بي … الفاينال كان تشابتر واحد فقط لا غير تخيلوا !! إضافة إلى 5 أوراق طلب مننا نذاكرها …\n\nإضافات: الدكتور أخلاااااق و يحب الطلاب يتفاعلون معه و يطلع برا المحاضرة و نتكلم عن المجتمع عموما … كان كلاس ممتع جدا …\n\nالخلاصة: +A نزل عنده وانت مغمض !!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1315758-mgt210", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/maxwell-heineck/118970/11", "user": "user2838", "ts": 1388960750000, "tid": 118970, "pn": 11}}]}', 1388960750000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9921-mgt210', 'stk-user9921', 'MGT 210', 'doc', '{"docs": [{"id": "stk-dr-f118970", "n": "Dr. Maxwell Heineck", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Mgt 210 Term162\n\nالتحضير : أول الكلاس وآخره وما عنده مشكلة مع اللي يتأخرون ولك غياب واحد مجاناً\n\nطريقة الشرح : يشرح على السلايدات وممكن يوزع اوراق لتوضيح الدرس أكثر ، ملفات الدروس موجودة وراح تعرف في كل يوم ايش راح تاخذ من البداية\n\nالكويزات : 5 كويزات ويحذف أسوأ واحد ، غالباً سهالات وتحتاج مذاكرة بسيطة\n\nالمياجر: كان فيه مدترم من ١٧ ، اسئلة المدترم مشابهة للكويزات بس يزيد من الMCQs والصح والخطا\n\nالفاينلات : MCQs و ثلاث أسئلة قصيرة وعشر فقرات بونص صح وخطا\n\nالقريد النهائي: B+\n\nالصوت: واضح ومفهوم\n\nإضافات : الدكتور الصراحة يعطيك فوق حقك في اعمال السنة ، فيه أشياء مجرد تسليمها يعني أنك أخذت الدرجة كاملة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1473551-mgt210", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/maxwell-heineck/118970/19", "user": "user9921", "ts": 1495384938000, "tid": 118970, "pn": 19}}]}', 1495384938000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-waleedx11-mgt210', 'stk-waleedx11', 'MGT 210', 'doc', '{"docs": [{"id": "stk-dr-f118970", "n": "Dr. Maxwell Heineck", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MGT210 TERM171\n\nالتحضير : ماله وقت محدد ، مرات بداية الكلاس مرات بالنص ومرات بالنهاية ، بس مش شديد أبدًا.\n\nطريقة الشرح : ساعات يفتح اللينكات اللي هو مسويها بالبلاكبورد ويشرح منها وساعات يشرح من السلايدات حقت المنهج ،، شرحه رهيب جدا ماشاء الله عليه والحلو ان أي نقطة يضرب عليها مثال من واقع الحياة أو شيء مضحك حصله يرتبط فيه فتترسخ المعلومة وما تنساها هههههههههههههههه.\n\nالكويزات : 5 كويزات يحذف فيهم أسوأ واحد ( بسيطة جدا تكون مذاكرتها من اللينكات اللي هو مسويها وغالبية الكلاس يجيبون فل ).\nالمياجر: ميدتيرم عليه 17% مش ميجر … مذاكرته الأفضل تكون من الكتاب مع مرور على التست بانك وأمورك طيبة ان شاء الله.\n\nالفاينلات : نفس نظام الميدتيرم ،، عليه 25% .\n\nالقريد النهائي: الدكتور أعطيه +A\n\nالصوت: واضح جدًا واكسنت أمريكي رهيب ماشاء الله هههههههه.\n\nإضافات :\n1- في الميدتيرم عطانا 10 أسئلة صح وخطأ ( بونص ) زيادة على أسئلة الميدتيرم ولك حرية الاختيار تحلها أو لا.\n2- في الفاينل برضو كان في سؤالين طوال عبارة عن 4 أقسام تحل 3 منهم بس واذا حليت الأربعة كلهم الرابع بونص ( يعني 14 نقطة بونص في الفاينل).\n3-الدكتور حبييييييييييييب الله يسعده لأبعد الحدود وفريندلي وفكاهي ولما يسولف بالكلاس نضحك لا شعوريا. 😆\n4- الكورس خفيف جدا جدا جدا معه وما يطلب أشياء كثير على عكس الدكتور الثاني ( ادوارد ) ، يعني تصلح وبقوة لترم ثقيل تاخذها معه.\n5- أحد الميزات اللي فيه اللي ما لقيته بدكتور ثاني أنه مرتب جدا جدا بالبلاكبورد لدرجة انه يرتب اللينكات بالتاريخ من بداية الترم الى نهايته واذا في اختبار أو تسليم شغلة تكون مكتوبة على اللينكات قبل ونفس اليوم فتستحي تسأله عن شيء لأن كل شيء قدامك موجود.\n6- القريد سهل ومقدور عليه عنده.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485724-mgt210", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/maxwell-heineck/118970/20", "user": "waleedx11", "ts": 1515404630000, "tid": 118970, "pn": 20}}]}', 1515404630000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_182-mgt210', 'stk-_182', 'MGT 210', 'doc', '{"docs": [{"id": "stk-dr-f118970", "n": "Dr. Maxwell Heineck", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MGT210-181\n\nالتحضير: غالبًا آخر المحاضرة\nطريقة الشرح: باوربوينت, يستطرد في الكلام ويضرب أمثلة, وكثير ما تكون الأمثلة قصص حصلت له, يسأل الطلاب ويصير فيه نقاش, المحاضرة رائعة باختصار.\nالكويزات: 5 كويزات بسيطة ويحذف الأسوأ منها, مذاكرتها تكون من ملفات بالبلاكبورد يحددها لكم.\nالمياجر: اختبار نصفي على 4 فصول, المذاكرة تكون من الكتاب وما فيه تحديد, لكن الأسئلة مباشرة وكلها (عدّد, عرّف, اذكر أمثلة على…) بالإضافة إلى سؤالين مقالي, الدكتور عطى كم سؤال بونص بس نسيت كم عددهم, 4 إذا ما كنت غلطان.\n* بالنسبة للمذاكرة من التيست بانك, نصيحة لا تعتمدون عليه, النصفي البعض اعتمد على كلام الطلاب السابقين وذاكر التيست بانك وتوهق, اقرأ الكتاب عشان ترتاح (وتستفيد!).\nالفاينل: عطانا 54 سؤال (غير محلولين) وقال الاختبار مرح يطلع منهم\nالقريد النهائي: A+\nالصوت: واضح\nإضافات:\n\n- الدكتور ماشاء الله خبرة في مجال العمل, اجتماعي وسافر لدول كثيرة وعمل في أكثر من دولة, هو المسؤول عن التوظيف في كلية الأعمال (كلية الإدارة الصناعية سابقًا), ومنسق بين الجامعة وأرامكو السعودية\n- خفيف دم, قلّما تمر محاضرة دون ما يحصل فيها فاصل فكاهي (أحيان يكون فاصل طويل)\n- شغله احترافي ومرتب جدًّا, من قبل بداية الترم يرفع على البلاكبورد جميع الأيام وإيش بتسوون في كل يوم, مُرفق مع ردي توضيح للمقصود.\n- إذا كنت محظوظ كفاية بالدراسة عنده, نصيحة استفد منه قدر المستطاع, الرجل موسوعة في مجال الإدارة والموارد البشرية, حظ الجامعة فيه.\n\nhttp://d.up-00.com/2019/01/154826779998451.png\n\nhttps://www.gulf-up.com/u29jcehufcum", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1505272-mgt210", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/maxwell-heineck/118970/21", "user": "_182", "ts": 1548267781000, "tid": 118970, "pn": 21}}]}', 1548267781000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-yousefli-mgt210', 'stk-yousefli', 'MGT 210', 'doc', '{"docs": [{"id": "stk-dr-f118970", "n": "Dr. Maxwell Heineck", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MGT 210 -191\n\nالشباب واللي سمعت عنه خرافي لكن تبين انه عايدي\nومعطينه سمعه عاليه مع انه ما اشوف الكلام هذا عشان كذا حبيت اشاركم رايي\n\nالتحضير :\n\nمايهتم بالتأخير لكن يدق في الكلام\nوفي نهاية الكلاس بالعادة\n\nطريقة الشرح :\nمن السلايدات ومن ملفات ثانية خاصة به\n\nالكويزات :\n\n٤ كويزات سهلة ويحذف اسوء واحد\nاذا تبي عالي مذاكرة ساعة بالكثير\nلكن دقيق في التصحيح\n\nالمياجر:\nميد تيرم مستواه متوسط\nالمتيريال قصير وسهل الصراحة بس يبغاله قوة حفظ…\nالاختيارات تكلمت عنها في الفاينل\nالرتن هم نفس طريقة الفاينل ستدي قايد\n\nالتصحيح:\n\nدقيق وينقصك احيانا على سبلنق او شيء كذا\nونادر يعطي احد فل لازم ينقص\nوالاسيمنتات شبه مستحيل يعطيك ١٠٠ !! ما ادري ليه\nمعقدها يطير عليك درجات كثيره\nبالنسبة للي يسلك الوضع تمام لانه يدف اللي تحت\nلكن اللي مسويه زين مراح يعطيه فل ما ادري ليه\n\nالفاينلات :\n\nعطانا study guide ما قصر الصراحة جاب منه لكن مو محلول لو حليته بتحل\nكل الرتن لانه مراح يطلع والاختيارات هم لو ذاكرت هذا راح تحل لكن الخيارات تي بي\nذاكر التي بي اخر نسخه كانت ٨ موجوده تحصلها في كوكتيل جاب منها\n\nمتوسط الى صعب\nوجايب صحح جمل ك انك تختبر انجليزي واجلس معاه بس\n\nالقريد النهائي:\nB+\n\nالصوت:\nواضح جدا\n\nإضافات :\nالمدرس هذا جدا طيب لكن الكلاس معاه احيانا ممل بحكم ان المادة تعتبر مملة لكن كلامها مهم وسهله وبعض المعلومات الكل يعرفها\nالكورس مريح جدا ومافي ضغط ومشكلته مع الحفظ فقط\nالهومورك: السي في ويدقق كثير لكن يعطيك درجة ف الاول مجرد تسليم فل\nالثانيه بعد التعديل هم ما يقصر لكن احلم فل.\nمتفهم ومتعاون… متساعد في تقييمه للبرزنتيشنز للناس اللي تحت لكن لو فوق يدقق ما يعطيك فل\nدكتور قيم وعنده خبره\nأحد الميزات اللي فيه اللي ما لقيته بدكتور ثاني أنه مرتب جدا جدا بالبلاكبورد كل شيء تحتاجه موجود تواريخ والخخ\n\nرافعينه العالم فوق ولما نزلت معه ما شفت الكلام ذا كله فأهو ممتاز لكن مو مثل ما سمعت\nفكلرت انه مره مره واو !!\n\nالملف قدامكم شوفوا بس كيف الفل شبه مستحيل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518389-mgt210", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/maxwell-heineck/118970/22", "user": "yousefli", "ts": 1577470471000, "tid": 118970, "pn": 22}}]}', 1577470471000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11151-mgt210', 'stk-user11151', 'MGT 210', 'doc', '{"docs": [{"id": "stk-dr-f118970", "n": "Dr. Maxwell Heineck", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MGT 210 - 191\n\nانخدعت بكلام الطلاب عنه؛ الدكتور شرحه ممل ولا فيه أي متعة في محاضراته.\nاختباراته صعبة وأيضًا متشدد وغير متعاون أبد وممكن يطير عليك قريدات ظلم ويروح عليك كل شي …\n\nنادم لأني سجلت معه، قاتلت عشان أنزل عنده لكن الواحد يتعلم والحياة تجارب …\nأخيرًا، ما أنصح أبد تنزل عنده والفائدة منه صفر ولا تغتر بكلام الناس وشعبة تقفل بدري.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518527-mgt210", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/maxwell-heineck/118970/23", "user": "user11151", "ts": 1577812461000, "tid": 118970, "pn": 23}}]}', 1577812461000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
